 static void RoundJoins(float[,] h,float[,] mask){int nz=h.GetLength(0),nx=h.GetLength(1),radius=48;for(int axis=0;axis<2;axis++){var src=(float[,])h.Clone();int length=axis==0?nx:nz,lines=axis==0?nz:nx;for(int b=512;b<length-1;b+=512)for(int k=0;k<lines;k++){Func<int,float> v=i=>axis==0?src[k,i]:src[i,k];Func<int,float> w=i=>axis==0?mask[k,i]:mask[i,k];float low=v(b-radius),high=v(b+radius),dl=(low-v(b-radius-8))/8,dh=(v(b+radius+8)-high)/8;float limit=Mathf.Abs(high-low)/(2*radius)+.3f;dl=Mathf.Clamp(dl,-limit,limit);dh=Mathf.Clamp(dh,-limit,limit);for(int i=-radius;i<=radius;i++){float u=(i+radius)/(2f*radius),u2=u*u,u3=u2*u;float y=(2*u3-3*u2+1)*low+(u3-2*u2+u)*2*radius*dl+(-2*u3+3*u2)*high+(u3-u2)*2*radius*dh;float weight=Mathf.Min(w(b+i),w(b))*S(0,12,radius-Mathf.Abs(i));if(axis==0)h[k,b+i]=Mathf.Lerp(src[k,b+i],y,weight);else h[b+i,k]=Mathf.Lerp(src[b+i,k],y,weight);}}}}
