 public static void BlendSnowTransitions(){
  if(Application.isPlaying)throw new Exception("Edit Mode required");var ts=MMTerrainBranchContrast20261007.Tiles();if(ts.Any(t=>EditorUtility.IsDirty(t.terrainData)))throw new Exception("Save or reload dirty TerrainData before authoring");if(ts.Any(t=>t.terrainData.heightmapResolution!=513||t.terrainData.size!=new Vector3(512,320,512)||t.transform.position.y!= -24))throw new Exception("Unexpected world grid layout");int ox=(int)ts.Min(t=>t.transform.position.x),oz=(int)ts.Min(t=>t.transform.position.z),nx=((int)ts.Max(t=>t.transform.position.x)-ox)/4+129,nz=((int)ts.Max(t=>t.transform.position.z)-oz)/4+129;var field=new float[nz,nx];var paints=ts.ToDictionary(t=>t,t=>t.terrainData.GetAlphamaps(0,0,t.terrainData.alphamapWidth,t.terrainData.alphamapHeight));
